class Solution:

	def carpetBox(self, A, B, C, D):
		count = 0
		max_cd = max(C, D)
		min_cd = min(C, D)
		max_ab = max(A, B)
		min_ab = min(A, B)
		while max_ab > max_cd or min_ab > min_cd:
			if max_ab > max_cd and max_ab == A:
				A //= 2
			elif max_ab > max_cd and max_ab == B:
				B //= 2
			elif min_ab > min_cd and min_ab == A:
				A //= 2
			elif min_ab > min_cd and min_ab == B:
				B //= 2
			count += 1
			max_ab = max(A, B)
			min_ab = min(A, B)
		return count
